test("generated application request adapter preserves payloads and terminal metadata", async () => {
  const handler: roles.ApplicationHandler = {
    ping(_context, request) {
      assert.deepEqual(request, {"t0":1700000000000,"rtt":42,"data":{"probe":"canonical"}});
      return {"t0":1700000000000,"t1":1700000000010,"t2":1700000000012,"owd":5,"data":{"probe":"canonical"}};
    },
    sessionInitialize(_context, request) {
      assert.deepEqual(request, {"application":{"id":"app-1"},"call":{"id":"call-1","session_id":"session-1","from":"+12025550100","to":"+12025550101"},"audio_codec_offerings":[{"id":"L16/8000/1","name":"L16","sample_rate":8000,"bit_depth":16,"channels":1}],"metadata":null});
      return {"audio_codec":null};
    },
    sessionTerminate(_context, request) {
      assert.deepEqual(request, {"reason":"completed"});
      return {};
    },
  };
  const registrations = roles.applicationRequestHandlers(handler);
  assert.deepEqual(
    registrations.map((registration) => [registration.method, registration.terminal]),
    [
      [catalog.METHOD_PING, false],
      [catalog.METHOD_SESSION_INITIALIZE, false],
      [catalog.METHOD_SESSION_TERMINATE, true],
    ],
  );
  {
    const registration = registrations.find((candidate) => candidate.method === catalog.METHOD_PING)!;
    const reply = await registration.handle(CONTEXT, catalog.decodePingRequest("{\"t0\":1700000000000,\"rtt\":42,\"data\":{\"probe\":\"canonical\"}}"));
    assert.equal(encodeWireJson(reply), "{\"t0\":1700000000000,\"t1\":1700000000010,\"t2\":1700000000012,\"owd\":5,\"data\":{\"probe\":\"canonical\"}}");
  }
  {
    const registration = registrations.find((candidate) => candidate.method === catalog.METHOD_SESSION_INITIALIZE)!;
    const reply = await registration.handle(CONTEXT, catalog.decodeSessionInitializeRequest("{\"application\":{\"id\":\"app-1\"},\"call\":{\"id\":\"call-1\",\"session_id\":\"session-1\",\"from\":\"+12025550100\",\"to\":\"+12025550101\"},\"audio_codec_offerings\":[{\"id\":\"L16/8000/1\",\"name\":\"L16\",\"sample_rate\":8000,\"bit_depth\":16,\"channels\":1}],\"metadata\":null}"));
    assert.equal(encodeWireJson(reply), "{\"audio_codec\":null}");
  }
  {
    const registration = registrations.find((candidate) => candidate.method === catalog.METHOD_SESSION_TERMINATE)!;
    const reply = await registration.handle(CONTEXT, catalog.decodeSessionTerminateRequest("{\"reason\":\"completed\"}"));
    assert.equal(encodeWireJson(reply), "{}");
  }
});

