test("generated application event adapter validates every peer event", async () => {
  const handler: roles.ApplicationEventHandler = {
    audioInfo(_context, event) { assert.deepEqual(event, {"read":{"bytes":0,"bytes_per_second":0,"bytes_total":0},"write":{"bytes":0,"bytes_per_second":0,"bytes_total":0}}); },
    callHangup(_context, event) { assert.deepEqual(event, {"reason":"caller"}); },
    dtmf(_context, event) { assert.deepEqual(event, {"seq":7,"pressed_at":1700000000000,"released_at":1700000000120,"digit":"5"}); },
    sessionUpdated(_context, event) { assert.deepEqual(event, {"audio_codec":{"id":"L16/8000/1","name":"L16","sample_rate":8000,"bit_depth":16,"channels":1}}); },
  };
  const registrations = roles.applicationEventHandlers(handler);
  await registrations.find((candidate) => candidate.event === catalog.EVENT_AUDIO_INFO)!.handle(CONTEXT, catalog.decodeAudioInfoEvent("{\"read\":{\"bytes\":0,\"bytes_per_second\":0,\"bytes_total\":0},\"write\":{\"bytes\":0,\"bytes_per_second\":0,\"bytes_total\":0}}"));
  await registrations.find((candidate) => candidate.event === catalog.EVENT_CALL_HANGUP)!.handle(CONTEXT, catalog.decodeCallHangupEvent("{\"reason\":\"caller\"}"));
  await registrations.find((candidate) => candidate.event === catalog.EVENT_DTMF)!.handle(CONTEXT, catalog.decodeDtmfEvent("{\"seq\":7,\"pressed_at\":1700000000000,\"released_at\":1700000000120,\"digit\":\"5\"}"));
  await registrations.find((candidate) => candidate.event === catalog.EVENT_SESSION_UPDATED)!.handle(CONTEXT, catalog.decodeSessionUpdatedEvent("{\"audio_codec\":{\"id\":\"L16/8000/1\",\"name\":\"L16\",\"sample_rate\":8000,\"bit_depth\":16,\"channels\":1}}"));
  const unknown = { request: async () => {}, event: async () => {} };
  assert.equal(roles.applicationAdapter(handler as unknown as roles.ApplicationHandler, handler, unknown).unknown, unknown);
});

