test("generated voice request adapter preserves payloads and terminal metadata", async () => {
  const handler: roles.VoiceHandler = {
    applicationMove(_context, request) {
      assert.deepEqual(request, {"reason":"handoff","application_id":"app-2"});
      return {"next_application_id":"app-2"};
    },
    audioBufferClear(_context, request) {
      assert.deepEqual(request, {});
      return {"len":320};
    },
    callHangup(_context, request) {
      assert.deepEqual(request, {"reason":"caller"});
      return {};
    },
    ping(_context, request) {
      assert.deepEqual(request, {"t0":1700000000000,"rtt":42,"data":{"probe":"canonical"}});
      return {"t0":1700000000000,"t1":1700000000010,"t2":1700000000012,"owd":5,"data":{"probe":"canonical"}};
    },
    recordingStart(_context, request) {
      assert.deepEqual(request, {"tags":["support","canonical"]});
      return {"id":"recording-1"};
    },
    recordingStop(_context, request) {
      assert.deepEqual(request, {"id":"recording-1"});
      return {};
    },
    sessionGet(_context, request) {
      assert.deepEqual(request, {"keys":["customer","attempt"]});
      return {"attempt":2,"customer":"Ada"};
    },
    sessionSet(_context, request) {
      assert.deepEqual(request, {"data":{"attempt":2,"customer":"Ada"}});
      return {};
    },
  };
  const registrations = roles.voiceRequestHandlers(handler);
  assert.deepEqual(
    registrations.map((registration) => [registration.method, registration.terminal]),
    [
      [catalog.METHOD_APPLICATION_MOVE, true],
      [catalog.METHOD_AUDIO_BUFFER_CLEAR, false],
      [catalog.METHOD_CALL_HANGUP, true],
      [catalog.METHOD_PING, false],
      [catalog.METHOD_RECORDING_START, false],
      [catalog.METHOD_RECORDING_STOP, false],
      [catalog.METHOD_SESSION_GET, false],
      [catalog.METHOD_SESSION_SET, false],
      [catalog.METHOD_SESSION_TERMINATE, false],
    ],
  );
  {
    const registration = registrations.find((candidate) => candidate.method === catalog.METHOD_APPLICATION_MOVE)!;
    const reply = await registration.handle(CONTEXT, catalog.decodeApplicationMoveRequest("{\"reason\":\"handoff\",\"application_id\":\"app-2\"}"));
    assert.equal(encodeWireJson(reply), "{\"next_application_id\":\"app-2\"}");
  }
  {
    const registration = registrations.find((candidate) => candidate.method === catalog.METHOD_AUDIO_BUFFER_CLEAR)!;
    const reply = await registration.handle(CONTEXT, catalog.decodeAudioBufferClearRequest("{}"));
    assert.equal(encodeWireJson(reply), "{\"len\":320}");
  }
  {
    const registration = registrations.find((candidate) => candidate.method === catalog.METHOD_CALL_HANGUP)!;
    const reply = await registration.handle(CONTEXT, catalog.decodeCallHangupRequest("{\"reason\":\"caller\"}"));
    assert.equal(encodeWireJson(reply), "{}");
  }
  {
    const registration = registrations.find((candidate) => candidate.method === catalog.METHOD_PING)!;
    const reply = await registration.handle(CONTEXT, catalog.decodePingRequest("{\"t0\":1700000000000,\"rtt\":42,\"data\":{\"probe\":\"canonical\"}}"));
    assert.equal(encodeWireJson(reply), "{\"t0\":1700000000000,\"t1\":1700000000010,\"t2\":1700000000012,\"owd\":5,\"data\":{\"probe\":\"canonical\"}}");
  }
  {
    const registration = registrations.find((candidate) => candidate.method === catalog.METHOD_RECORDING_START)!;
    const reply = await registration.handle(CONTEXT, catalog.decodeRecordingStartRequest("{\"tags\":[\"support\",\"canonical\"]}"));
    assert.equal(encodeWireJson(reply), "{\"id\":\"recording-1\"}");
  }
  {
    const registration = registrations.find((candidate) => candidate.method === catalog.METHOD_RECORDING_STOP)!;
    const reply = await registration.handle(CONTEXT, catalog.decodeRecordingStopRequest("{\"id\":\"recording-1\"}"));
    assert.equal(encodeWireJson(reply), "{}");
  }
  {
    const registration = registrations.find((candidate) => candidate.method === catalog.METHOD_SESSION_GET)!;
    const reply = await registration.handle(CONTEXT, catalog.decodeSessionGetRequest("{\"keys\":[\"customer\",\"attempt\"]}"));
    assert.equal(encodeWireJson(reply), "{\"attempt\":2,\"customer\":\"Ada\"}");
  }
  {
    const registration = registrations.find((candidate) => candidate.method === catalog.METHOD_SESSION_SET)!;
    const reply = await registration.handle(CONTEXT, catalog.decodeSessionSetRequest("{\"data\":{\"attempt\":2,\"customer\":\"Ada\"}}"));
    assert.equal(encodeWireJson(reply), "{}");
  }
  await assert.rejects(
    registrations.find((candidate) => candidate.method === catalog.METHOD_SESSION_TERMINATE)!.handle(CONTEXT, catalog.decodeSessionTerminateRequest("{\"reason\":\"completed\"}")),
    (error: unknown) => {
      assert.ok(error instanceof ProtocolHandlerError);
      assert.equal(error.wire.code, 501);
      assert.equal(error.wire.message, "session.terminate is not supported. please use application.move or call.hangup instead");
      return true;
    },
  );
});

